"""Presentation assets for the local support workspace."""

CSS = r'''
:root{font:15px/1.5 "Segoe UI",Calibri,sans-serif;color:#142d3b;background:#f2f5f6;--ink:#142d3b;--accent:#087f7c;--muted:#526b78;--line:#d8e2e5;--paper:#fff}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}a{color:var(--accent);text-underline-offset:3px}button,.button-link{border:0;background:var(--accent);color:white;padding:11px 18px;border-radius:7px;font-weight:600;font-size:14px;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px}button:hover,.button-link:hover{background:#066663}button:active{transform:translateY(1px)}button:disabled{background:#e3eaec;color:#5b707b;cursor:not-allowed}button:disabled:active{transform:none}:focus-visible{outline:3px solid #238eac;outline-offset:3px}::selection{background:#bde7de;color:#142d3b}input,textarea{caret-color:var(--accent)}*{scrollbar-width:thin;scrollbar-color:#b8cbd0 transparent}.skip-link{position:fixed;left:12px;top:-60px;z-index:20;background:white;padding:12px}.skip-link:focus{top:12px}
.app-shell{min-height:100dvh;display:grid;grid-template-columns:224px minmax(0,1fr)}.sidebar{background:var(--ink);color:#d2e1e7;padding:36px 24px 24px;display:flex;flex-direction:column;position:sticky;top:0;height:100dvh}.wordmark{font-size:25px;font-weight:650;color:white;text-decoration:none;line-height:1.15;letter-spacing:-.025em}.wordmark span{display:block;font-size:21px;font-weight:400;color:#a9d7d1}.sidebar-caption{font-size:12px;margin:16px 0 40px;color:#c0d1d9}.sidebar nav{display:grid;gap:8px}.sidebar nav a{padding:12px 14px;color:#cedce3;text-decoration:none;border-radius:7px;font-weight:500}.sidebar nav a:hover{background:#213f4f;color:#fff}.sidebar nav a[aria-current=page]{background:#d9eeea;color:#163e3d;font-weight:650}.sidebar-footer{margin-top:auto;padding-top:28px}.connection{font-size:12px;color:#d0dbe1;display:block;margin-bottom:12px}.connection:before{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:#b7c3c9;margin-right:8px}.connection.connected:before{background:#86d3b3}.sidebar-footer button{background:transparent;border:1px solid #55707e;color:white;width:100%;padding:8px}.sidebar-footer .form-status{color:#d1e1e8}
main#main-content{padding:30px 40px;max-width:1480px;width:100%;margin:auto;height:100dvh;overflow:auto;display:flex;flex-direction:column;min-width:0}.page-heading{display:flex;align-items:center;justify-content:space-between;flex:none;margin-bottom:24px}.page-heading h1{font-size:28px;letter-spacing:-.025em;font-weight:650;line-height:1.25;margin:0 0 6px}.page-heading p{font-size:14px;color:var(--muted);margin:0}h2{font-size:19px;font-weight:650;line-height:1.3;margin:0 0 8px}p{max-width:70ch}.muted,.hint{color:var(--muted);font-size:13px}.hint{margin:10px 0 0}.notice{padding:12px 16px;background:#e2f3eb;color:#22583f;border:1px solid #b9dacc;border-radius:7px;font-size:14px;flex:none;margin:0 0 20px}.notice.error{background:#fff0eb;color:#92391f;border-color:#e4bcac}.form-status{margin:8px 0 0;color:var(--accent);font-size:13px}.form-status:empty,#operation-status:empty{display:none}
.settings-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(250px,.8fr);gap:32px;align-items:start;max-width:1040px}.settings-section{background:white;padding:28px;border:1px solid var(--line);border-radius:12px;min-width:0}.ai-section{grid-column:1;grid-row:1}.seller-section{grid-column:2;grid-row:1}.settings-section>.muted{margin:0 0 24px}.settings-section form{max-width:520px}.settings-section label{margin-top:18px}label{display:block;font-size:13px;font-weight:600;margin:15px 0 7px}input,select,textarea{width:100%;padding:11px 12px;background:white;border:1px solid #b6c9d0;border-radius:6px;color:var(--ink);min-width:0}input::placeholder,textarea::placeholder{color:#607984;opacity:1}input:hover,select:hover,textarea:hover{border-color:#73969f}input:focus,select:focus,textarea:focus{border-color:var(--accent);outline:2px solid #b9ded8;outline-offset:1px}form>button{margin-top:18px}.connection-action{display:flex;align-items:center;gap:16px;margin-top:24px;border-top:1px solid var(--line);padding-top:20px}.connection-action form{flex:none}.connection-action button{margin:0}.connection-action .hint{font-size:12px;margin:0;max-width:28ch}.advanced{margin-top:24px;border-top:1px solid var(--line);padding-top:18px}.advanced summary{font-size:13px;cursor:pointer;color:var(--muted);font-weight:600}.advanced-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.file-panel{background:white;border:1px solid var(--line);border-radius:12px;padding:32px;max-width:850px}.file-panel>.muted{margin-bottom:24px}.file-panel input[type=file]{padding:24px 18px;border:1px dashed #8eafb4;background:#f5faf9;margin-top:8px}.file-panel input[type=file]::file-selector-button{border:0;background:#dceee9;color:#235d58;border-radius:5px;padding:10px 14px;margin-right:14px;cursor:pointer}.file-list{list-style:none;margin:16px 0;padding:0;font-size:13px;display:grid;gap:8px}.file-list li{padding:9px 12px;background:#f2f6f7;border-radius:5px;overflow-wrap:anywhere}.file-count{font-size:13px;color:var(--muted);margin-top:8px}
.chat{background:var(--paper);border:1px solid var(--line);border-radius:12px;display:flex;flex-direction:column;min-height:400px;flex:1;overflow:hidden}.chat-top{padding:20px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:16px;flex:none}.chat-top p{margin:5px 0 0;font-size:13px}.chat-top h2{font-size:17px;margin:0}.chat-top button{margin:0;background:#edf4f5;color:#2b5363;font-size:13px}.history{padding:10px 24px;border-bottom:1px solid var(--line);font-size:13px;flex:none}.history summary{cursor:pointer;color:var(--muted)}.history ul{margin:8px 0;padding-left:20px;max-height:120px;overflow:auto}.transcript{overflow:auto;flex:1;min-height:140px;padding:26px;display:flex;flex-direction:column;gap:22px}.empty{margin:auto;text-align:center;max-width:420px;padding:20px}.empty h3{font-size:24px;letter-spacing:-.02em;font-weight:600;margin:0 0 12px}.empty p{margin:0;font-size:14px;color:var(--muted);line-height:1.7}.bubble{max-width:80%;align-self:flex-start}.bubble.user{align-self:flex-end}.role{font-size:12px;color:var(--muted);margin:0 0 6px}.bubble.user .role{text-align:right}.text{padding:13px 17px;background:#edf3f5;border-radius:2px 12px 12px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.65}.user .text{background:#e0efeb;color:#153f3b;border-radius:12px 2px 12px 12px}.composer{padding:18px 24px;border-top:1px solid var(--line);background:#fbfdfd;flex:none}.composer form{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:12px}.composer label{position:absolute;width:1px;height:1px;overflow:hidden}.composer textarea{resize:vertical;min-height:72px;max-height:160px}.composer button{margin:0;min-height:44px}.composer>.hint{font-size:11px;margin-top:8px}.composer:has(>textarea){display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:12px}.composer textarea:disabled{resize:none;background:#f1f5f6;border-color:#d4e0e4}.setup-needed{display:flex;align-items:center;justify-content:space-between;gap:24px;background:#eef6f4;padding:18px 24px;border-top:1px solid #d1e5df;flex:none}.setup-needed strong{font-size:14px}.setup-needed p{font-size:13px;margin:4px 0 0;color:#405f5c}.setup-needed .button-link{white-space:nowrap;font-size:13px}.chat-error{margin:12px 24px}.chat:has(.setup-needed) .empty h3{font-size:22px}#operation-status{margin:8px 24px;color:var(--accent);font-size:13px}
main#main-content.login-shell{height:auto;max-width:none;min-height:100dvh;display:grid;place-items:center;padding:24px;background:#eaf0f2}.login{width:100%;max-width:420px;background:white;padding:36px;border:1px solid var(--line);border-radius:12px}.login h2{font-size:27px;margin:20px 0 10px}.login .brand{font-size:20px;font-weight:600;color:#28635e}.login button{width:100%}.login .muted{font-size:14px}.login .notice{margin-top:20px}
@media(min-width:1600px){main#main-content{padding:36px 56px}}
@media(max-width:1000px){.app-shell{grid-template-columns:180px minmax(0,1fr)}.sidebar{padding:28px 18px}.wordmark{font-size:22px}.wordmark span{font-size:19px}main#main-content{padding:24px}.settings-grid{grid-template-columns:1fr;gap:20px}.seller-section{grid-column:1;grid-row:2}.ai-section{grid-row:1}.connection-action{flex-wrap:wrap}}
@media(max-width:760px){.app-shell{display:block}.sidebar{position:static;height:auto;padding:16px 20px;display:grid;grid-template-columns:1fr auto;gap:14px}.wordmark{font-size:19px;display:flex;align-items:baseline;gap:5px}.wordmark span{font-size:19px}.sidebar-caption,.connection{display:none}.sidebar nav{grid-column:1/-1;grid-row:2;display:flex;gap:8px}.sidebar nav a{flex:1;text-align:center;font-size:13px;padding:10px 6px}.sidebar-footer{grid-column:2;grid-row:1;padding:0;margin:0}.sidebar-footer button{padding:5px 12px}.sidebar-footer .form-status{display:none}main#main-content{height:auto;min-height:calc(100dvh - 120px);padding:24px 16px}.page-heading{margin-bottom:20px}.page-heading h1{font-size:25px}.page-heading p{font-size:13px}.chat{min-height:480px;height:calc(100dvh - 230px);flex:auto}.settings-section,.file-panel{padding:24px}.setup-needed{gap:12px;padding:16px;flex-wrap:wrap}.chat-top{padding:16px}.chat-top p{display:none}.transcript{padding:18px;min-height:120px}.composer{padding:14px}.bubble{max-width:92%}.connection-action{gap:12px}.connection-action .hint{max-width:100%}.advanced-grid{gap:0 12px}.file-panel input[type=file]{font-size:12px;padding:18px 12px}.empty h3{font-size:21px}.empty{padding:10px}.empty p{font-size:13px}}
@media(max-width:760px){input,select,textarea{font-size:16px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important}}
'''

JS = r'''
document.querySelectorAll('input[type=file]').forEach(input=>input.addEventListener('change',()=>{
 const list=document.getElementById('file-list');list.replaceChildren();
 Array.from(input.files).forEach(file=>{const li=document.createElement('li');li.textContent=file.name;list.appendChild(li)});
 let count=document.querySelector('.file-count');if(!count){count=document.createElement('p');count.className='file-count';list.after(count)}
 count.textContent=input.files.length+' de 6 arquivos selecionados';
}));
const provider=document.getElementById('provider');
if(provider)provider.addEventListener('change',()=>{window.location.assign('/?view=settings&provider='+encodeURIComponent(provider.value))});
document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{
 if(form.dataset.busy){event.preventDefault();return}form.dataset.busy='1';
 let status=form.querySelector('.form-status');if(!status){status=document.createElement('p');status.className='form-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.appendChild(status)}
 status.textContent=form.action.endsWith('/chat/send')?'Respondendo…':form.action.endsWith('/ai/test')?'Testando a conexão…':'Salvando…';
 form.querySelectorAll('button').forEach(button=>button.disabled=true);
}));
const message=document.getElementById('message');
if(message&&message.form)message.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();message.form.requestSubmit()}});
const transcript=document.getElementById('transcript');if(transcript)transcript.scrollTop=transcript.scrollHeight;
window.addEventListener('pageshow',()=>document.querySelectorAll('form[data-busy]').forEach(form=>{delete form.dataset.busy;form.querySelectorAll('button').forEach(button=>button.disabled=false)}));
'''
